mapper.select:
SELECT  FROM growth_evidence_use
WHERE owner_id=#{owner} AND target_version_id=#{targetVersionId}
  AND requirement_id=#{requirementId} AND evidence_key=#{evidenceKey}

SELECT  FROM growth_evidence_use
WHERE owner_id=#{owner} AND target_id=#{targetId} AND target_version_id=#{targetVersionId}
  AND created_at < #{asOf}
AND requirement_id=#{requirementId}
AND status=#{status}

  AND (created_at < #{afterCreatedAt} OR (created_at=#{afterCreatedAt} AND id > #{afterId}))

ORDER BY created_at DESC,id ASC LIMIT #{limit}

SELECT owner_id,use_id,revision,change_kind,snapshot_json,source_stamp_json,target_stamp,preview_hash,created_at
FROM growth_evidence_use_history WHERE owner_id=#{owner} AND use_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}

mapper.update:
UPDATE growth_evidence_use SET revision=#{row.revision},coverage=#{row.coverage},
  comparability_json=#{row.comparabilityJson},reason=#{row.reason},status=#{row.status},updated_at=#{row.updatedAt}
WHERE owner_id=#{row.ownerId} AND id=#{row.id} AND revision=#{expected}

mapper.select:
SELECT  FROM growth_next_step_preference
WHERE owner_id=#{owner} AND created_at < #{asOf}
AND visibility=#{visibility}
AND subject_kind=#{subjectKind}

  AND (created_at < #{afterCreatedAt} OR (created_at=#{afterCreatedAt} AND id > #{afterId}))

ORDER BY created_at DESC,id ASC LIMIT #{limit}

SELECT owner_id,preference_id,revision,change_kind,snapshot_json,created_at
FROM growth_next_step_preference_history WHERE owner_id=#{owner} AND preference_id=#{id}
AND revision < #{before}
ORDER BY revision DESC LIMIT #{limit}
